cd multicode; mkdir -p .cache/check-click; cat > .cache/check-click/run.mjs <<'EOF'
import { createRequire } from 'module';
const require = createRequire('multicode/.cache/pw/');
const { chromium } = require('playwright-core');
const OUT='multicode/obelisk/build/full/check-click-2026-10-31';
const b = await chromium.launch({args:['--use-gl=swiftshader','--enable-unsafe-swiftshader']});
async function run(tag, vp, q='', mobile=false){
  const ctx = await b.newContext({viewport:vp, hasTouch:mobile, isMobile:mobile});
  const p = await ctx.newPage();
  p.on('console',m=>{ if(m.type()==='error') console.log(tag,'console',m.text()); });
  await p.goto('http://127.0.0.1:8765/ui/main/index.html'+q);
  await p.waitForFunction(()=>window.gameReady||window.gameError,null,{timeout:60000});
  console.log(tag, 'err', await p.evaluate(()=>window.gameError), await p.evaluate(()=>[window.game.W,window.game.H,window.game.raster]));
  const box = await p.locator('#game').boundingBox(); console.log(tag,'box',JSON.stringify(box));
  await p.screenshot({path:`${OUT}/${tag}-1-before.png`});
  console.log(tag,'peek0',JSON.stringify(await p.evaluate(()=>window.game.app.peek())));
  // scan grid of taps
  const W=await p.evaluate(()=>window.game.W), H=await p.evaluate(()=>window.game.H);
  const hits=[];
  for(let gy=0.1;gy<1;gy+=0.1) for(let gx=0.1;gx<1;gx+=0.2){
    const r = await p.evaluate(([x,y])=>{window.game.app.newGame(); const r=window.game.app.tap(x,y); return r;},[gx*W,gy*H]);
    if(r.ignored!==undefined||r.screen!=='hub') hits.push([Math.round(gx*W),Math.round(gy*H),JSON.stringify(r)]);
  }
  console.log(tag,'API​ taps non-trivial:',JSON.stringify(hits));
  await p.evaluate(()=>window.game.app.newGame());
  if(hits.length){
    const [x,y]=hits[0];
    const bx=box.x+x*box.width/W, by=box.y+y*box.height/H;
    if(mobile) await p.touchscreen.tap(bx,by); else await p.mouse.click(bx,by);
    await p.waitForTimeout(500);
    console.log(tag,'after real click',x,y,await p.evaluate(()=>window.game.app.screenName()));
    await p.screenshot({path:`${OUT}/${tag}-2-after.png`});
  }
  await ctx.close();
}
await run('desktop1920',{width:1920,height:1080});
await run('desktop1920-w1000',{width:1920,height:1080},'?pack=gray&w=1000');
await run('mobile',{width:390,height:844},'?pack=gray&w=500',true);
await b.close();
EOF
node .cache/check-click/run.mjs 2>&1 | tail -30

