  await real(200,240,'click Workshop tile (200,240)');
  await p.screenshot({path:`${OUT}/${tag}-2-workshop.png`});
  await real(250,908,'click hub button (250,908)');
  await real(200,560,'click Upgrades tile (task<3)');
  await real(100,560,'click tile screen0 (100,560)');
  await real(300,240,'click tile 10 (300,240)');
  await p.screenshot({path:`${OUT}/${tag}-3-after-others.png`});
  console.log(tag,'peek',JSON.stringify(await p.evaluate(()=>{const q=window.game.app.peek();return {screen:q.screen,gold:q.gold,task:q.task,obelisk:q.obelisk}})));
'''
open(p,'w').write(s[:a]+new+s[b:])
EOF
