const ini = fs.readFileSync('multicode/.cache/obelisk-full/main633/rich.ini','utf8');
for (const [pack,port] of [['gray',8765],['local',8766]]) {
  await p.goto(`http://127.0.0.1:${port}/ui/main/index.html?pack=${pack}&fresh=1`);
  await p.waitForFunction(()=>window.gameReady||window.gameError,null,{timeout:200000});
  console.log(pack,'err',await p.evaluate(()=>window.gameError));
  await p.evaluate(async (t)=>{window.game.app.importSave(t); await window.game.redraw();}, ini);
  await p.waitForTimeout(500);
  console.log(pack,'peek',JSON.stringify(await p.evaluate(()=>{const q=window.game.app.peek();return {screen:q.screen,gold:q.gold,task:q.task,obelisk:q.obelisk}})));
  await p.screenshot({path:`${OUT}/${pack}-rich-1-hub.png`});
  const box = await p.locator('#game').boundingBox();
  for (const [x,y,l] of [[200,240,'workshop tile'],[250,908,'hub btn'],[250,908,'hub btn again'],[200,560,'upgrades tile']]) {
    await p.mouse.click(box.x+x*box.width/500, box.y+y*box.height/960); await p.waitForTimeout(1500);
    console.log(pack,l,await p.evaluate(()=>window.game.app.screenName()), await p.locator('#status').textContent());
    await p.screenshot({path:`${OUT}/${pack}-rich-${l.replace(/ /g,'_')}.png`});
  }
}
await b.close();
EOF
